CHAINS=[{'chain': '600289-这笔占款是否已经收回？', 'source': '1225661950', 'pages': [1, 2], 'subject': '这笔占款是否已经收回？', 'changed': '11月6日指定银行账户实收11,042.73万元，11月7日公告称非经营性占款全部清偿、相关全额清偿承诺已履行。将该笔待清偿更新为已清偿，不倒填7月3日。', 'open': '占款实收清偿已关闭；两宗恢复执行案件、正式撤销及经营现金继续核。', 'supporting': []}, {'chain': '600289-一个结案是否解决全部担保问题？', 'source': '1225467171', 'pages': [1, 2], 'subject': '一个结案是否解决全部担保问题？', 'changed': '8月天合国际案以执行完毕方式对公司结案，本案未强制执行公司资产。10月31日仍另列德润和华地恒基两案恢复执行、本金合计28,256万元和异议待核。天合结案及11月占款清偿不能代替这两案最新裁定。', 'open': '占款实收清偿已关闭；两宗恢复执行案件、正式撤销及经营现金继续核。', 'supporting': [{'source': '1225649078', 'pages': [2], 'state': '对应原件，主体、金额与时点分别核。'}]}, {'chain': '600265-诉讼终审是否等于财务警示解除？', 'source': '1225657722', 'pages': [1, 2], 'subject': '诉讼终审是否等于财务警示解除？', 'changed': '11月5日披露沧州银行案二审驳回上诉、维持原判，案件为终审。可以更新该案上诉待决事项；不能从该案终审推导年度扣除后收入门槛修复、所有股权解冻或正式摘星。', 'open': '保留财务收入门槛与持续经营条件，个案终审不等于摘星，旧扣非单位冲突不关闭。', 'supporting': []}, {'chain': '600302-清算报告出来，是否已经完成清算？', 'source': '1225648277', 'pages': [2], 'subject': '清算报告出来，是否已经完成清算？', 'changed': '10月末清算审计正式文件已出、评估报告和清算方案仍为初稿，后续按程序推进。与6月底相比有实质文书进展，不能写成清算注销完成或内控审计已转无保留。', 'open': '核清算注销完成、独立内控审计和正式撤销；股权工商登记不替代这些条件。', 'supporting': []}, {'chain': '600337-债务豁免是否只是签约设想？', 'source': '1225590892', 'pages': [1, 2, 3], 'subject': '债务豁免是否只是签约设想？', 'changed': '10月1日公告称累计859,923,263.84元豁免已实施完成；这是已经发生的债务减免，与投资协议等待法院条件分开。8月、9月分批金额及累计金额不可重复相加。', 'open': '核两主体各自计划批准、投资款实际到账、登记和剩余逾期；资本公积增厚不当经营利润现金。', 'supporting': []}, {'chain': '600337-8.60亿元豁免是否等于利润和现金改善？', 'source': '1225662164', 'pages': [17], 'subject': '8.60亿元豁免是否等于利润和现金改善？', 'changed': '11月7日专项报告核查将859,923,263.84元债务豁免作为权益性交易计入资本公积。不能写成等额当期净利润或经营现金流入。母公司可转增资本公积余额1,456,302,218.10元不等于已经转增；实际实施仍须按计划表决、法院批准和实施日条件。', 'open': '核两主体各自计划批准、投资款实际到账、登记和剩余逾期；资本公积增厚不当经营利润现金。', 'supporting': []}, {'chain': '600337-债务减免后，是否已经恢复偿债能力？', 'source': '1225667450', 'pages': [1, 2], 'subject': '债务减免后，是否已经恢复偿债能力？', 'changed': '截至11月10日逾期借款及商票仍120,440.26万元，已扣除豁免对应借款本金21,082.87万元；不能再从余额重复扣同一笔。原累计豁免含不同类型债权，与借款本金扣除额口径不同。1—9月审计仍提示持续经营重大不确定性、归母亏损90,777.42万元。', 'open': '核两主体各自计划批准、投资款实际到账、登记和剩余逾期；资本公积增厚不当经营利润现金。', 'supporting': [{'source': '1225662165', 'pages': [2, 3], 'state': '对应原件，主体、金额与时点分别核。'}]}, {'chain': '600337-协议已生效，为何仍不能把投资款当实收', 'source': '1225438035', 'pages': [10, 11], 'subject': '协议已生效，为何仍不能把投资款当实收', 'changed': '7月21日签约、23日披露；协议经各方签章后生效。拟10转10.13、增加1455679113股；小磁368000000股按1.47元，其他330000000股按1.61元，产业批合计投资对价1072260000元。', 'open': '全款支付在上市公司及美克集团两份重整计划均获法院批准后10工作日内；保证金签约后10工作日内支付，约定不等于已收到。股数以最终登记为准，增加股份不是全部送给旧股东，价格不当二级市场底价。', 'supporting': []}, {'chain': '600337-财务投资人增加了，是否等于资金全到位', 'source': '1225572315', 'pages': [1], 'subject': '财务投资人增加了，是否等于资金全到位', 'changed': '9月18日第二批7家签约，拟1.61元/股认购250090654.01股、对价约402645952.96元；第三批100500000股约161805000元；第四批94120199股约151533520.39元。', 'open': '均为拟定安排，不能把分批签约金额当实收；原件小数股数保留，不自行取整，也不将这些数字当最终登记后股数或确定稀释结果。', 'supporting': [{'source': '1225586280', 'pages': [2], 'state': '第三批9月24日及28日签约，29日披露。'}, {'source': '1225590893', 'pages': [2], 'state': '第四批9月29日签约，10月1日披露。'}]}, {'chain': '600337-无保留审计是否说明重整已完成', 'source': '1225662165', 'pages': [2, 3], 'subject': '无保留审计是否说明重整已完成', 'changed': '11月7日披露的1—9月审计为无保留意见，仍附持续经营重大不确定性；报告出具时仍为预重整，计划草案磋商完善，正式受理和表决通过均不确定。', 'open': '无保留不是重整已完成，也不消除持续经营条件。法院对控股股东及关联企业合并重整不替代上市公司正式受理，11月12日逾期公告仍称预重整推进。', 'supporting': [{'source': '1225601827', 'pages': [1], 'state': '10月控股股东等三家关联企业合并重整，主体范围分开。'}, {'source': '1225667450', 'pages': [1], 'state': '11月债务压力与投资协议进展并存。'}]}, {'chain': '600265-转为盈利之后，年度门槛是否已经修复', 'source': '1225647037', 'pages': [1], 'subject': '转为盈利之后，年度门槛是否已经修复', 'changed': '前三季归母2680077.19元、扣非2012539.20元，经营现金49681405.21元，较半年小幅亏损改善；累计收入81332861.33元，同比下降41.91%。', 'open': '普通前三季收入不当全年扣除后营收，不能凭盈利直接宣告财务警示解除。汇银剥离与博达49%股权无偿受赠改变合并范围和资产结构，不能把全部变动归因经营内生恢复。', 'supporting': [{'source': '1225497053', 'pages': [7], 'state': '半年归母-209327.84元，经营现金正；剥离、受赠与经营分别核。'}]}, {'chain': '600289-大幅增收，是否已经恢复现金盈利', 'source': '1225649024', 'pages': [1, 3], 'subject': '大幅增收，是否已经恢复现金盈利', 'changed': '前三季收入935836441.11元，同比增长385.55%，归母-142073833.38元、扣非-141061455.85元，经营现金-155616035.32元。', 'open': '增收不等于盈利或现金净流入；报告解释硬件定制收入增加，现金同比基期含收到占款偿付款。11月本次清偿在三季度以后，不倒填该期现金或利润。', 'supporting': [{'source': '1225511738', 'pages': [5], 'state': '半年收入增长761.49%，归母和经营现金仍负。'}]}, {'chain': '600302-收购登记完成，是否解决旧内控问题', 'source': '1225670825', 'pages': [1], 'subject': '收购登记完成，是否解决旧内控问题', 'changed': '11月14日披露昊友航材51%股权工商变更已完成，交易对价4924.05万元；可以关闭该交易工商登记待办。', 'open': '不据工商登记证明全额付款、业绩承诺兑现或旧海菱内控问题消除。前三季归母-70661733.47元、扣非-72532739.35元、经营现金-78616576.42元，经营约束继续。', 'supporting': [{'source': '1225637186', 'pages': [1], 'state': '前三季营收225948259.98元，同比下降12.71%。'}, {'source': '1225648277', 'pages': [2], 'state': '海菱清算与内控程序另核。'}]}]
