def followup_view(inputs, prior):
    packet=inputs.get('sixteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('sixteenth period packet changed')
    if prior is None or prior['counts']['after']!=106 or packet['prior_digest']!=digest(prior):raise ValueError('sixteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('sixteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=34 or len(packet['sources'])!=34 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('sixteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('sixteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('sixteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('sixteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('sixteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('sixteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('sixteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('sixteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('sixteenth period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('sixteenth period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
            if row['quarter_basis']!=expected:raise ValueError('sixteenth period quarter label changed')
        elif row['quarter_basis']!='nine_month_minus_h1':raise ValueError('sixteenth period derived quarter label changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('sixteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('sixteenth period windows changed')
    if [(r['symbol'],r['metric'],r['quarter_difference_yuan'])for r in FINANCIAL if r['quarter_basis']=='reported_and_difference_conflict']!=[('600302','recurring_profit','-0.01'),('600337','operating_cash','-0.01')]:raise ValueError('sixteenth period original arithmetic differences changed')
    return {'through':'2026-11-19','title':'收回占款、豁免债务和签约，分别改变了什么？','answer':'信通这笔占款已实收清偿，两宗恢复执行案件另核；景谷对应诉讼已终审，财务警示门槛仍单独看。标准清算文书和收购登记推进，但不能据此确认内控有效。美克豁免已实施且计入资本公积，协议签章生效与双计划获批后的付款实施分开；股价反转不能直接归因于签约或经营恢复。','chains':CHAINS,'financial_bridge':FINANCIAL,'phase_comparisons':PHASES,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':34,'new_files':34,'reused_files':0,'pages':1079,'new_pages':1079,'viewed_pages':len(VISUAL),'initial_coverage':106,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'34份1079页下载原件中目视核23关键页，133条期间目录，不称全文已阅或全部催化已穷尽。102公告窗口88满14未满，93独立股票端点跨渠道核；另核28阶段比较的32端点，不把重合端点累计当独立证据。16半年指标中6报告同比相符，10不适用仅另算；单季11直接一致、3现金差额，标准扣非与美克现金各有0.01元原件算术差异，两值并列，不放宽精确门槛或宣称已消除。美克资本公积、盈利与现金、两主体司法阶段分别看，价格和同期背景不识别公告净因果。旧期初事实、金额单位冲突、宁科历史目录与原件差异及旧报价缺口保持，无通用经验晋级。','method_promotions':0}
